export type Post = {
  id: string
  title: string
  content: string
  createdAt: Date
}

const posts: Post[] = []

export async function getPosts(): Promise<Post[]> {
  return [...posts]
}

export async function createPost(data: {
  title: string
  content: string
}): Promise<Post> {
  const post: Post = {
    id: crypto.randomUUID(),
    title: data.title,
    content: data.content,
    createdAt: new Date(),
  }
  posts.unshift(post)
  return post
}

